<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { Truck, Route, FileText, Video, ShieldAlert, BadgeCheck } from 'lucide-vue-next';
import { useRouter } from 'vue-router';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import { label, number, params, stamp, useResponsiveDrawer, type PageResult } from '../province-monitoring';
import ProvinceMonitoringMap from './ProvinceMonitoringMap.vue';
import EvidenceTimeline from './EvidenceTimeline.vue';
import ProvincePageState from './ProvincePageState.vue';
const props = withDefaults(defineProps<{ modelValue: boolean; vehicleId: string; workspaceId?: string; initialTab?: string }>(), { initialTab: 'overview' });
const emit = defineEmits<{ 'update:modelValue': [value: boolean]; tab: [value: string] }>();
const router = useRouter(), loading = ref(false), error = ref(''), detail = ref<any>(), tab = ref('overview'), sectionLoading = ref(false), sectionError = ref('');
const drawerSize = useResponsiveDrawer(850), session = useSessionStore();
const records = ref<any[]>([]), recordTotal = ref(0), recordPage = ref(1), recordId = ref(''), dateRange = ref<[string, string] | null>(null), track = ref<any[]>([]), latestTrack = ref<any[]>([]), trackTruncated = ref(false), trackMode = ref('record'), cursor = ref(0), playing = ref(false), sectionRows = ref<any[]>([]), sectionTotal = ref(0), sectionPage = ref(1), eventKind = ref('ALERT');
let generation = 0, sectionGeneration = 0, controller: AbortController | undefined;
const tabs = computed(() => [{ key: 'overview', name: '档案总览', icon: Truck, show: true }, { key: 'tracks', name: '运行轨迹', icon: Route, show: detail.value?.access.tracks }, { key: 'records', name: '运行记录', icon: FileText, show: detail.value?.access.records }, { key: 'accidents', name: '事故与视频', icon: Video, show: detail.value?.access.accidents }, { key: 'alerts', name: '告警违规', icon: ShieldAlert, show: detail.value?.access.alerts || detail.value?.access.violations }, { key: 'licenses', name: '通行许可', icon: BadgeCheck, show: detail.value?.access.licenses }].filter(t => t.show));
const vehicle = computed(() => detail.value?.vehicle), trackStart = computed(() => Date.parse(track.value[0]?.recordedAt) || 0), trackEnd = computed(() => Date.parse(track.value.at(-1)?.recordedAt) || 0);
const fields = computed(() => vehicle.value ? [['统一编码', vehicle.value.unifiedCode], ['VIN', vehicle.value.vin], ['设备编号', vehicle.value.deviceNo], ['厂商车型', `${vehicle.value.model?.manufacturer?.name ?? ''} ${vehicle.value.model?.name ?? ''}`], ['车辆用途', label(vehicle.value.vehicleType)], ['所属地市', vehicle.value.cityName], ['监管辖区', vehicle.value.organization?.name], ['建档编号', vehicle.value.archive?.archiveNo], ['生命周期', label(vehicle.value.archive?.lifecycleStatus)], ['建档日期', stamp(vehicle.value.archive?.registeredAt)]] : []);
function query(extra: Record<string, unknown> = {}) { return params({ workspaceId: props.workspaceId, ...extra }); }
async function load() {
  const current = ++generation; sectionGeneration++; controller?.abort(); controller = new AbortController();
  detail.value = undefined; error.value = ''; sectionError.value = ''; loading.value = true; playing.value = false; records.value = []; track.value = []; latestTrack.value = []; sectionRows.value = []; recordPage.value = sectionPage.value = 1; recordId.value = ''; dateRange.value = null;
  try { const result = await api<any>(`/province/vehicles/${props.vehicleId}?${query()}`, { signal: controller.signal }); if (current !== generation) return; detail.value = result; tab.value = tabs.value.some(t => t.key === props.initialTab) ? props.initialTab : 'overview'; if (tab.value === 'overview' && result.latestRecord && result.access.tracks) { void api<any>(`/province/vehicles/${props.vehicleId}/tracks?${query({ recordId: result.latestRecord.id })}`, { signal: controller.signal }).then(r => { if (current === generation) latestTrack.value = r.points; }).catch(() => {}); } await loadSection(); }
  catch (reason) { if (current === generation && !controller.signal.aborted) error.value = reason instanceof Error ? reason.message : '车辆档案读取失败'; }
  finally { if (current === generation) loading.value = false; }
}
async function loadRecords() { const data = await api<PageResult>(`/province/vehicles/${props.vehicleId}/records?${query({ page: recordPage.value, pageSize: 5 })}`); return data; }
async function queryTrack() {
  const current = ++sectionGeneration; playing.value = false; sectionError.value = ''; sectionLoading.value = true;
  try { if (trackMode.value === 'record' && !recordId.value || trackMode.value === 'time' && !dateRange.value) { track.value = []; return; } const result = await api<any>(`/province/vehicles/${props.vehicleId}/tracks?${query(trackMode.value === 'record' ? { recordId: recordId.value } : { from: dateRange.value?.[0], to: dateRange.value?.[1] })}`); if (current !== sectionGeneration) return; track.value = result.points; trackTruncated.value = result.truncated; cursor.value = Date.parse(result.points[0]?.recordedAt) || 0; }
  catch (reason) { if (current === sectionGeneration) sectionError.value = reason instanceof Error ? reason.message : '轨迹读取失败'; }
  finally { if (current === sectionGeneration) sectionLoading.value = false; }
}
async function loadSection() {
  if (!detail.value || !props.modelValue) return; const current = ++sectionGeneration; sectionError.value = ''; sectionLoading.value = true; playing.value = false;
  try {
    if (['tracks', 'records'].includes(tab.value)) { if (!detail.value.access.records) { records.value = []; if (tab.value === 'tracks') trackMode.value = 'time'; return; } const result = await loadRecords(); if (current !== sectionGeneration) return; records.value = result.items; recordTotal.value = result.total; if (tab.value === 'tracks') { recordId.value = result.items.some(row => row.id === recordId.value) ? recordId.value : result.items[0]?.id ?? ''; await queryTrack(); } }
    if (tab.value === 'accidents' || tab.value === 'alerts') {
      if (tab.value === 'alerts' && eventKind.value === 'ALERT' && !detail.value.access.alerts) eventKind.value = 'VIOLATION';
      const path = tab.value === 'accidents' ? '/province/accidents' : eventKind.value === 'ALERT' ? '/province/alerts' : `/province/vehicles/${props.vehicleId}/violations`;
      const result = await api<PageResult>(`${path}?${query({ vehicleId: props.vehicleId, page: sectionPage.value, pageSize: 10 })}`); if (current !== sectionGeneration) return; sectionRows.value = result.items; sectionTotal.value = result.total;
    }
  } catch (reason) { if (current === sectionGeneration) sectionError.value = reason instanceof Error ? reason.message : '资料读取失败'; }
  finally { if (current === sectionGeneration) sectionLoading.value = false; }
}
function changeTab(value: string) { const keepRecordPage = ['tracks', 'records'].includes(tab.value) && ['tracks', 'records'].includes(value); tab.value = value; sectionPage.value = 1; if (!keepRecordPage) recordPage.value = 1; sectionRows.value = []; track.value = []; void loadSection(); emit('tab', value); }
function showRecord(id: string) { recordId.value = id; trackMode.value = 'record'; changeTab('tracks'); }
function openAccident(id: string) { emit('update:modelValue', false); void router.push({ path: '/province/accidents', query: { accidentId: id, vehicleId: props.vehicleId, ...(props.workspaceId ? { workspaceId: props.workspaceId } : {}) } }); }
function follow() { if (!vehicle.value) return; emit('update:modelValue', false); void router.push({ path: '/province/cockpit', query: { cityCode: vehicle.value.cityCode, organizationId: vehicle.value.organizationId, enterpriseId: vehicle.value.enterpriseId, vehicleId: vehicle.value.id, mapMode: 'vehicles' } }); }
watch(() => [props.modelValue, props.vehicleId, props.workspaceId], () => { if (props.modelValue && props.vehicleId) void load(); else { generation++; sectionGeneration++; controller?.abort(); playing.value = false; } }, { immediate: true });
watch(() => props.initialTab, value => { if (props.modelValue && detail.value && tabs.value.some(t => t.key === value) && value !== tab.value) changeTab(value); });
onBeforeUnmount(() => { generation++; sectionGeneration++; controller?.abort(); });
</script>
<template><el-drawer :model-value="modelValue" class="pm-drawer" :size="drawerSize" :modal="false" :lock-scroll="false" title="车辆监管档案" destroy-on-close @update:model-value="emit('update:modelValue', $event)"><ProvincePageState :loading="loading" :error="error" @retry="load"><template v-if="vehicle"><header class="pm-dossier-identity"><span class="pm-truck-avatar"><Truck :size="28"/></span><div><h2>{{ vehicle.businessNo }}<small>一车一档</small></h2><p>{{ vehicle.enterprise.name }} · {{ vehicle.cityName }}</p></div><el-tag :type="vehicle.onlineStatus === 'ONLINE' ? 'success' : 'info'" effect="plain">{{ label(vehicle.onlineStatus) }}</el-tag></header><div class="pm-dossier-report">最后上报 {{ stamp(vehicle.realtimeStatus?.heartbeatAt) }} · {{ label(vehicle.realtimeStatus?.drivingState) }}</div><nav class="pm-dossier-tabs" aria-label="单车档案内容"><button v-for="item in tabs" :key="item.key" type="button" :aria-pressed="tab === item.key" @click="changeTab(item.key)"><component :is="item.icon" :size="14"/>{{ item.name }}</button></nav>
<template v-if="tab === 'overview'"><section class="pm-detail-card"><h3>车辆身份与监管信息</h3><dl class="pm-facts"><div v-for="[name, value] in fields" :key="String(name)"><dt>{{ name }}</dt><dd>{{ value || '—' }}</dd></div></dl></section><section v-if="detail.latestRecord" class="pm-detail-card"><header><h3>最近运行</h3><el-button v-if="detail.access.tracks" link type="primary" @click="showRecord(detail.latestRecord.id)">查看完整轨迹</el-button></header><div class="pm-recent-run"><ProvinceMonitoringMap v-if="latestTrack.length" :track="latestTrack" height="205px"/><div v-else class="pm-no-map">最近行程暂无可展示轨迹</div><dl class="pm-facts"><div><dt>行程时间</dt><dd>{{ stamp(detail.latestRecord.startedAt) }} — {{ stamp(detail.latestRecord.endedAt) }}</dd></div><div><dt>运行里程</dt><dd>{{ number(detail.latestRecord.mileage, ' km') }}</dd></div><div><dt>起点</dt><dd>{{ detail.latestRecord.startAddress || '—' }}</dd></div><div><dt>终点</dt><dd>{{ detail.latestRecord.endAddress || '—' }}</dd></div></dl></div></section><section v-if="detail.access.accidents" class="pm-detail-card"><header><h3>事故与视频</h3><el-button link type="primary" @click="changeTab('accidents')">查看全部</el-button></header><button v-for="row in detail.accidents" :key="row.id" type="button" class="pm-incident-row" @click="openAccident(row.id)"><time>{{ stamp(row.occurredAt) }}</time><strong>{{ row.title }}</strong><el-tag size="small" effect="plain">{{ label(row.status) }}</el-tag><span>{{ row.videoCount ? `${row.videoCount}段录像` : '视频未接入' }}</span></button><el-empty v-if="!detail.accidents.length" description="该车暂无事故记录" :image-size="48"/></section></template>
<ProvincePageState v-else :loading="sectionLoading" :error="sectionError" @retry="tab === 'tracks' ? queryTrack() : loadSection()">
<template v-if="tab === 'tracks'"><div class="pm-track-query"><el-radio-group v-model="trackMode" @change="playing = false; track = []"><el-radio-button value="record" :disabled="!detail.access.records">按行程</el-radio-button><el-radio-button value="time">按时间</el-radio-button></el-radio-group><template v-if="trackMode === 'time'"><el-date-picker v-model="dateRange" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ssZ" start-placeholder="开始时间" end-placeholder="结束时间" aria-label="轨迹时间范围"/><el-button type="primary" @click="queryTrack">查询轨迹</el-button></template></div><div v-if="trackMode === 'record'" class="pm-record-picker"><button v-for="row in records" :key="row.id" type="button" :aria-pressed="recordId === row.id" @click="recordId = row.id; queryTrack()"><strong>{{ row.businessNo }}</strong><small>{{ stamp(row.startedAt) }} · {{ number(row.mileage, ' km') }}</small></button><el-pagination v-if="recordTotal > 5" v-model:current-page="recordPage" :total="recordTotal" :page-size="5" layout="prev,pager,next" small @current-change="loadSection"/></div><el-alert v-if="trackTruncated" title="轨迹超过5000点，当前仅展示前5000点，请缩小查询时间范围" type="warning" :closable="false"/><template v-if="track.length"><ProvinceMonitoringMap :key="`${vehicleId}-${recordId}-${trackStart}`" :track="track" :cursor-time="cursor" height="360px"/><EvidenceTimeline v-model="cursor" v-model:playing="playing" :from="trackStart" :to="trackEnd"/><div class="pm-inline-facts"><span>轨迹点 <b>{{ track.length }}</b></span><span>最高速度 <b>{{ number(Math.max(...track.map(p => p.speed)), ' km/h') }}</b></span><span>时间按原始采集记录回放</span></div></template><el-empty v-else description="所选行程或时间范围暂无轨迹" :image-size="64"/></template>
<template v-if="tab === 'records'"><el-table :data="records" empty-text="暂无运行记录"><el-table-column prop="businessNo" label="行程编号" min-width="170"/><el-table-column label="时间" min-width="150"><template #default="{ row }">{{ stamp(row.startedAt) }}<small class="pm-subline">{{ stamp(row.endedAt) }}</small></template></el-table-column><el-table-column label="里程" width="95"><template #default="{ row }">{{ number(row.mileage, ' km') }}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{ row }">{{ label(row.status) }}</template></el-table-column><el-table-column v-if="detail.access.tracks" label="操作" width="95"><template #default="{ row }"><el-button link type="primary" @click="showRecord(row.id)">查看轨迹</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="recordPage" :total="recordTotal" :page-size="5" layout="total,prev,pager,next" @current-change="loadSection"/></template>
<template v-if="tab === 'accidents'"><el-table :data="sectionRows" empty-text="该车暂无事故记录"><el-table-column label="事故" min-width="230"><template #default="{ row }"><strong>{{ row.title }}</strong><small class="pm-subline">{{ row.businessNo }} · {{ stamp(row.occurredAt) }}</small></template></el-table-column><el-table-column label="处置状态" width="110"><template #default="{ row }">{{ label(row.status) }}</template></el-table-column><el-table-column label="视频资料" width="115"><template #default="{ row }">{{ row.videoCount ? `${row.videoCount} 段录像` : '未接入' }}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link type="primary" @click="openAccident(row.id)">事故回溯</el-button></template></el-table-column></el-table></template>
<template v-if="tab === 'alerts'"><div class="pm-track-query"><el-radio-group v-model="eventKind" @change="sectionPage = 1; loadSection()"><el-radio-button v-if="detail.access.alerts" value="ALERT">风险告警</el-radio-button><el-radio-button v-if="detail.access.violations" value="VIOLATION">违规记录</el-radio-button></el-radio-group></div><el-table :data="sectionRows" empty-text="该车暂无对应安全记录"><el-table-column prop="title" label="事项" min-width="180"/><el-table-column label="发生时间" width="145"><template #default="{ row }">{{ stamp(row.occurredAt) }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{ row }">{{ label(row.status) }}</template></el-table-column><el-table-column label="最近处理" min-width="180"><template #default="{ row }">{{ row.lastComment || row.reviewComment || row.determination || '暂无处理记录' }}</template></el-table-column></el-table></template>
<el-pagination v-if="['accidents','alerts'].includes(tab)" v-model:current-page="sectionPage" :total="sectionTotal" :page-size="10" layout="total,prev,pager,next" @current-change="loadSection"/>
<template v-if="tab === 'licenses'"><el-table :data="detail.licenses" empty-text="该车暂无许可记录"><el-table-column prop="licenseNo" label="许可编号" min-width="170"/><el-table-column label="有效期" min-width="200"><template #default="{ row }">{{ stamp(row.issuedAt) }} — {{ stamp(row.expiresAt) }}</template></el-table-column><el-table-column label="许可状态" width="110"><template #default="{ row }">{{ label(row.status) }}</template></el-table-column><el-table-column prop="operationArea" label="通行范围" min-width="180"/></el-table></template>
</ProvincePageState>
</template></ProvincePageState><template #footer><div v-if="vehicle" class="pm-drawer-actions"><el-button v-if="session.user?.permissions.includes('dashboard:view')" @click="follow">进入实时跟踪</el-button><el-button v-if="detail.access.tracks" type="primary" @click="changeTab('tracks')">查看运行轨迹</el-button></div></template></el-drawer></template>

